// spec: specs/edit-listing-save-changes.md (3.4–3.6) · кейс: .qa/tests/edit-listing-save-changes/EDIT-SAVE-03.md · #917a7d
// Нужно своё объявление: QA_EDIT_LISTING_ID=<id> [QA_EDIT_LISTING_ROLE=user]; без него — skip.
// ПРОД: PATCH business?id=eq.<id> перехватывается и отвечается локально 200, на сервер не уходит; прочие не-GET — abort.
import { test, expect, Page, Locator } from '@playwright/test';
import { EDIT_ID, EDIT_ROLE, SKIP_REASON, LOAD, SAVE, NEXT, TITLE_PH, interceptEdit, openEdit } from './edit-listing.helpers';

const OK_TEXT = 'השינויים נשמרו בהצלחה';
const ERR_FRAGMENT = 'אירעה שגיאה בשמירת המודעה';
const DRAFT_ERR = 'לא הצלחנו לשמור את הטיוטה';

test.use({ storageState: `../auth/${EDIT_ROLE}.json`, serviceWorkers: 'block' });

async function qaTitle(page: Page) {
  const title = page.getByPlaceholder(TITLE_PH);
  const newTitle = `QA-AUTO ${(await title.inputValue()).replace(/^QA-AUTO /, '')}`.slice(0, 90);
  await title.fill(newTitle);
  return newTitle;
}

/** Прямоугольник toast успеха (текст) и плавающих кнопок WhatsApp / נגישות (по подписи/тексту). */
async function boxes(page: Page, toast: Locator) {
  const t = await toast.boundingBox();
  const vw = await page.evaluate(() => document.documentElement.clientWidth || window.innerWidth);
  const vh = await page.evaluate(() => window.innerHeight);
  const floats: { name: string; box: { x: number; y: number; width: number; height: number } }[] = [];
  for (const name of [/whatsapp|וואטסאפ/i, /נגישות/]) {
    const el = page.getByRole('link', { name }).or(page.getByRole('button', { name })).first();
    if (await el.isVisible().catch(() => false)) {
      const b = await el.boundingBox();
      if (b) floats.push({ name: String(name), box: b });
    }
  }
  return { t, vw, vh, floats };
}

const intersects = (a: { x: number; y: number; width: number; height: number }, b: typeof a) =>
  a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;

test.describe('Редактирование объявления — toast успеха после «שמור שינויים» (#917a7d)', () => {
  test.skip(!EDIT_ID, SKIP_REASON);

  for (const device of ['@desktop', '@android']) {
    test(`Успешное «שמור שינויים» — toast «${OK_TEXT}» вверху экрана, переход в «המודעות שלי» #917a7d ${device}`, async ({ page }) => {
      const { patches, passed, state } = await interceptEdit(page, EDIT_ID);
      await openEdit(page, EDIT_ID, state);
      const newTitle = await qaTitle(page);

      await page.getByRole('button', { name: SAVE, exact: true }).click();
      await page.waitForURL(/\/mybusinesses/, LOAD);
      const toast = page.getByText(OK_TEXT).first();
      // «מה רצוי» #917a7d: «אחרי שמירה מוצלחת — להציג הודעה קצרה»; «בראש המסך» — комментарий программиста
      await expect(toast, `toast «${OK_TEXT}»`).toBeVisible(LOAD);

      const { t, vw, vh, floats } = await boxes(page, toast);
      expect(t, 'у toast есть прямоугольник').not.toBeNull();
      expect(t!.y, 'toast в верхней трети экрана').toBeLessThan(vh / 3);
      expect(t!.y, 'toast не выше края экрана').toBeGreaterThanOrEqual(0);
      expect(t!.x, 'toast не за левым краем').toBeGreaterThanOrEqual(0);
      expect(t!.x + t!.width, 'toast не за правым краем').toBeLessThanOrEqual(vw + 0.5);
      if (device === '@android') {
        for (const f of floats) expect(intersects(t!, f.box), `toast не перекрыт кнопкой ${f.name}`).toBe(false);
      }

      await expect(page.getByText(ERR_FRAGMENT), 'нет toast ошибки').toHaveCount(0);
      await expect(page.getByText(DRAFT_ERR), 'нет ложного сообщения черновика (#0c6087)').toHaveCount(0);
      expect(patches.length, 'ровно один PATCH на нажатие').toBe(1);
      expect(Object.values(patches[0].body), 'в PATCH новая כותרת').toContain(newTitle);
      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }

  test(`«שמור שינויים» со шага 3 — тот же toast «${OK_TEXT}» #917a7d @desktop`, async ({ page }) => {
    const { patches, passed, state } = await interceptEdit(page, EDIT_ID);
    await openEdit(page, EDIT_ID, state);
    const newTitle = await qaTitle(page);

    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByText('משך פעילות העסק (שנים/חודשים)'), 'шаг 2 «נתונים נוספים»').toBeVisible(LOAD);
    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByRole('heading', { name: 'העלאת תמונות', exact: true }), 'шаг 3 — фото').toBeVisible(LOAD);
    await expect(page.getByText(DRAFT_ERR), 'при переходах 1→2→3 нет «לא הצלחנו לשמור את הטיוטה» (#0c6087)').toHaveCount(0);

    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await page.waitForURL(/\/mybusinesses/, LOAD);
    await expect(page.getByText(OK_TEXT).first(), `toast «${OK_TEXT}»`).toBeVisible(LOAD);
    expect(patches.length, 'PATCH сохранения отправлен').toBeGreaterThan(0);
    expect(Object.values(patches[patches.length - 1].body), 'последний PATCH содержит новую כותרת').toContain(newTitle);
    expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
  });
});
